<?php
declare(strict_types=1);
namespace App\Infrastructure\Persistence\Doctrine\QuestionBank;
use App\Domain\QuestionBank\ReadModel\PublishedQuestion;use App\Domain\QuestionBank\Repository\EditorialQuestionRepositoryInterface;use App\Infrastructure\Persistence\Doctrine\QuestionBank\Entity\QuestionRecord;use Doctrine\ORM\EntityManagerInterface;
final class DoctrineEditorialQuestionRepository implements EditorialQuestionRepositoryInterface {public function __construct(private readonly EntityManagerInterface $em,private readonly DoctrinePublishedQuestionRepository $reader){}public function listDrafts(int $offset,int $limit):array{$records=$this->em->createQueryBuilder()->select('q')->from(QuestionRecord::class,'q')->where('q.status=:s')->setParameter('s','DRAFT')->orderBy('q.createdAt','DESC')->setFirstResult($offset)->setMaxResults($limit)->getQuery()->getResult();$ids=array_map(static fn(QuestionRecord $q)=>$q->id,$records);return['items'=>$this->reader->findByIds($ids),'total'=>(int)$this->em->createQueryBuilder()->select('COUNT(q.id)')->from(QuestionRecord::class,'q')->where('q.status=:s')->setParameter('s','DRAFT')->getQuery()->getSingleScalarResult()];}public function exists(string $id):bool{return (int)$this->em->createQueryBuilder()->select("COUNT(q.id)")->from(QuestionRecord::class,"q")->where("q.id=:id")->setParameter("id",$id)->getQuery()->getSingleScalarResult()>0;}public function publish(string $id):bool{return $this->em->createQueryBuilder()->update(QuestionRecord::class,'q')->set('q.status',':published')->set('q.updatedAt',':now')->where('q.id=:id')->andWhere('q.status=:draft')->andWhere('q.correctOptionId IS NOT NULL')->setParameter('published','PUBLISHED')->setParameter('draft','DRAFT')->setParameter('now',new \DateTimeImmutable('now'))->setParameter('id',$id)->getQuery()->execute()===1;}}
